-- card: A payment card. Holds only tokens and masked data; PAN and CVV live in the vault.
CREATE TABLE card (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  card_program_id              uuid NOT NULL REFERENCES card_program(id),
  card_product_id              uuid NOT NULL REFERENCES card_product(id),
  customer_id                  uuid NOT NULL,
  business_customer_id         uuid,
  pan_token                    varchar(64) NOT NULL,
  pan_fingerprint              varchar(64),
  bin                          varchar(11) NOT NULL,
  last4                        varchar(4) NOT NULL,
  expiry_month                 integer NOT NULL,
  expiry_year                  integer NOT NULL,
  sequence_number              integer NOT NULL DEFAULT 0,
  cardholder_name              varchar(26) NOT NULL,
  form_factor                  varchar(40) NOT NULL CHECK (form_factor IN ('VIRTUAL', 'PHYSICAL')),
  status                       varchar(40) NOT NULL DEFAULT 'CREATED' CHECK (status IN ('CREATED', 'ACTIVE', 'FROZEN', 'BLOCKED', 'LOST', 'STOLEN', 'EXPIRED', 'CLOSED', 'REPLACED')),
  status_reason                varchar(255),
  linked_account_type          varchar(40) NOT NULL CHECK (linked_account_type IN ('DEPOSIT_ACCOUNT', 'WALLET', 'CREDIT_LINE', 'PREPAID_LEDGER', 'JIT_PROGRAM')),
  ledger_account_id            uuid NOT NULL,
  deposit_account_id           uuid,
  wallet_id                    uuid,
  credit_line_id               uuid,
  replaces_card_id             uuid REFERENCES card(id),
  pin_set                      boolean NOT NULL DEFAULT false,
  pin_try_count                integer NOT NULL DEFAULT 0,
  activated_at                 timestamptz,
  frozen_at                    timestamptz,
  closed_at                    timestamptz,
  nickname                     varchar(64),
  metadata                     jsonb,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_card_pan_token UNIQUE (tenant_id, pan_token)
);
COMMENT ON TABLE card IS 'A payment card. Holds only tokens and masked data; PAN and CVV live in the vault.';
